import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import * as DropdownMenu from "@radix-ui/react-dropdown-menu";
import { Slot } from "@radix-ui/react-slot";
import { cn } from "@/lib/utils";

export type ButtonVariant =
  | "default"
  | "secondary"
  | "outline"
  | "ghost"
  | "white"
  | "destructive"
  | "link";

export type ButtonSize = "sm" | "md" | "lg" | "icon";

export interface ButtonProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "disabled"> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  asChild?: boolean;
  loading?: boolean;
  disabled?: boolean;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
  /** Animate the left icon on hover. */
  leftIconMotion?: "trash" | "mail";
  /** Animate the right icon on hover. */
  rightIconMotion?: "arrow" | "download";
}

const base =
  "relative inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap rounded-[10px] " +
  "text-sm font-medium select-none touch-manipulation " +
  "transition-[background,background-color,border-color,color,box-shadow,opacity] duration-200 ease-[cubic-bezier(0.22,1,0.36,1)] " +
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[color-mix(in_srgb,var(--foreground)_20%,transparent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)] " +
  "disabled:pointer-events-none disabled:opacity-45 " +
  "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0";

const pressable = "active:duration-100";

const variants: Record<ButtonVariant, string> = {
  default: cn(
    pressable,
    "border border-[color-mix(in_srgb,var(--foreground)_14%,transparent)] bg-[var(--foreground)] text-[var(--background)] " +
      "shadow-[0_1px_1px_rgba(0,0,0,0.04),0_1px_3px_rgba(0,0,0,0.10)] " +
      "hover:border-[color-mix(in_srgb,var(--foreground)_20%,transparent)] hover:bg-[color-mix(in_srgb,var(--foreground)_94%,var(--background)_6%)] " +
      "hover:shadow-[0_1px_2px_rgba(0,0,0,0.06),0_6px_20px_-6px_rgba(0,0,0,0.16)] " +
      "active:border-[color-mix(in_srgb,var(--foreground)_16%,transparent)] active:bg-[var(--foreground)] active:shadow-[0_1px_2px_rgba(0,0,0,0.08)]",
  ),
  secondary: cn(
    pressable,
    "border border-[var(--border-strong)] bg-[var(--surface)] text-[var(--foreground)] " +
      "shadow-[0_1px_1px_rgba(0,0,0,0.03),0_1px_2px_rgba(0,0,0,0.04)] " +
      "hover:border-[color-mix(in_srgb,var(--foreground)_16%,transparent)] hover:bg-[var(--surface-muted)] " +
      "hover:shadow-[0_1px_2px_rgba(0,0,0,0.05),0_6px_20px_-8px_rgba(0,0,0,0.10)] " +
      "active:bg-[color-mix(in_srgb,var(--surface-muted)_90%,var(--foreground)_10%)] " +
      "dark:shadow-[0_1px_2px_rgba(0,0,0,0.30)] dark:hover:shadow-[0_1px_2px_rgba(0,0,0,0.40),0_6px_20px_-8px_rgba(0,0,0,0.45)]",
  ),
  outline: cn(
    pressable,
    "border border-[var(--border-strong)] bg-transparent text-[var(--foreground)] " +
      "hover:border-[color-mix(in_srgb,var(--foreground)_24%,transparent)] hover:bg-[color-mix(in_srgb,var(--foreground)_4%,transparent)] " +
      "hover:shadow-[0_1px_2px_rgba(0,0,0,0.04),0_6px_20px_-10px_rgba(0,0,0,0.10)] " +
      "active:border-[color-mix(in_srgb,var(--foreground)_20%,transparent)] active:bg-[color-mix(in_srgb,var(--foreground)_7%,transparent)] " +
      "dark:hover:shadow-[0_1px_2px_rgba(0,0,0,0.20),0_6px_20px_-10px_rgba(0,0,0,0.40)]",
  ),
  ghost: cn(
    pressable,
    "border border-transparent bg-transparent text-[var(--muted-foreground)] " +
      "hover:bg-[color-mix(in_srgb,var(--foreground)_5%,transparent)] hover:text-[var(--foreground)] " +
      "active:bg-[color-mix(in_srgb,var(--foreground)_9%,transparent)]",
  ),
  white: cn(
    pressable,
    "border border-black/[0.06] bg-white text-neutral-950 " +
      "shadow-[0_1px_1px_rgba(0,0,0,0.04),0_1px_3px_rgba(0,0,0,0.08)] " +
      "hover:border-black/[0.10] hover:bg-neutral-50 " +
      "hover:shadow-[0_1px_2px_rgba(0,0,0,0.06),0_8px_24px_-8px_rgba(0,0,0,0.14)] " +
      "active:bg-neutral-100 active:shadow-[0_1px_2px_rgba(0,0,0,0.06)] " +
      "dark:border-white/85 dark:bg-white dark:text-neutral-950 dark:shadow-[0_1px_2px_rgba(0,0,0,0.24)] " +
      "dark:hover:border-white dark:hover:bg-neutral-50 " +
      "dark:hover:shadow-[0_1px_2px_rgba(0,0,0,0.10),0_8px_24px_-8px_rgba(255,255,255,0.18)] " +
      "dark:active:bg-neutral-100",
  ),
  destructive: cn(
    pressable,
    "border border-red-600/75 bg-red-600 text-white " +
      "shadow-[0_1px_1px_rgba(127,29,29,0.20),0_1px_3px_rgba(127,29,29,0.16)] " +
      "hover:border-red-500/85 hover:bg-red-500 " +
      "hover:shadow-[0_1px_2px_rgba(127,29,29,0.24),0_8px_24px_-8px_rgba(239,68,68,0.30)] " +
      "active:border-red-700 active:bg-red-700 active:shadow-[0_1px_2px_rgba(127,29,29,0.28)] " +
      "dark:border-red-500/65 dark:hover:shadow-[0_8px_24px_-8px_rgba(248,113,113,0.28)]",
  ),
  link:
    "h-auto border border-transparent bg-transparent px-0 font-medium text-[var(--foreground)] underline-offset-4 " +
    "hover:text-[var(--muted-foreground)] hover:underline hover:decoration-[color-mix(in_srgb,var(--foreground)_35%,transparent)] " +
    "active:text-[var(--foreground)]",
};

const sizes: Record<ButtonSize, string> = {
  sm: "h-8 gap-1.5 px-3.5 text-xs",
  md: "h-9 gap-2 px-4",
  lg: "h-10 gap-2 px-5 text-[15px]",
  icon: "h-9 w-9 gap-0 p-0",
};

const ICON_SHELL = "relative z-10 inline-flex shrink-0";

const ICON_MOTION_SHELL =
  "btn-icon-motion inline-flex shrink-0 origin-center will-change-transform";

const leftIconMotionClass = {
  trash: cn(
    ICON_MOTION_SHELL,
    "motion-safe:group-hover:animate-[button-trash-shake_0.42s_cubic-bezier(0.36,0.07,0.19,0.97)_both]",
  ),
  mail: cn(
    ICON_MOTION_SHELL,
    "motion-safe:group-hover:animate-[button-mail-lift_0.44s_cubic-bezier(0.22,1,0.36,1)_both]",
  ),
} as const;

const rightIconMotionClass = {
  arrow: cn(
    ICON_MOTION_SHELL,
    "motion-safe:transition-transform motion-safe:duration-[320ms] motion-safe:ease-[cubic-bezier(0.22,1,0.36,1)]",
    "motion-safe:group-hover:translate-x-1",
    "motion-safe:group-active:translate-x-0.5",
  ),
  download: cn(
    ICON_MOTION_SHELL,
    "motion-safe:group-hover:animate-[button-download-tick_0.4s_cubic-bezier(0.34,1.2,0.64,1)_both]",
  ),
} as const;

const BUTTON_ICON_KEYFRAMES_ID = "button-icon-keyframes";

function ensureButtonIconKeyframes() {
  if (typeof document === "undefined") return;
  if (document.getElementById(BUTTON_ICON_KEYFRAMES_ID)) return;

  const style = document.createElement("style");
  style.id = BUTTON_ICON_KEYFRAMES_ID;
  style.textContent = `
    @keyframes button-trash-shake {
      0%, 100% { transform: translate3d(0, 0, 0) rotate(0deg); }
      20% { transform: translate3d(-0.5px, -1px, 0) rotate(-5deg); }
      40% { transform: translate3d(0.5px, -1.5px, 0) rotate(4deg); }
      60% { transform: translate3d(-0.5px, -0.5px, 0) rotate(-2.5deg); }
      80% { transform: translate3d(0, -0.5px, 0) rotate(1deg); }
    }
    @keyframes button-mail-lift {
      0% { transform: translate3d(0, 0, 0) rotate(0deg); }
      40% { transform: translate3d(2.5px, -3.5px, 0) rotate(-7deg); }
      100% { transform: translate3d(0, 0, 0) rotate(0deg); }
    }
    @keyframes button-download-tick {
      0%, 100% { transform: translate3d(0, 0, 0); }
      45% { transform: translate3d(0, 3.5px, 0); }
      100% { transform: translate3d(0, 0, 0); }
    }
    @media (prefers-reduced-motion: reduce) {
      .btn-icon-motion {
        animation: none !important;
        transition: none !important;
        transform: none !important;
      }
    }
  `;
  document.head.appendChild(style);
}

export function buttonVariants({
  variant = "default",
  size = "md",
  className,
}: {
  variant?: ButtonVariant;
  size?: ButtonSize;
  className?: string;
} = {}) {
  return cn(base, variants[variant], sizes[size], className);
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant = "default",
      size = "md",
      asChild = false,
      loading = false,
      disabled = false,
      leftIcon,
      rightIcon,
      leftIconMotion,
      rightIconMotion,
      children,
      type,
      onClickCapture,
      tabIndex,
      ...props
    },
    ref,
  ) => {
    const Comp = asChild ? Slot : "button";
    const isDisabled = disabled || loading;
    const hasIconMotion = Boolean(leftIconMotion || rightIconMotion);

    const handleClickCapture = React.useCallback(
      (event: React.MouseEvent<HTMLButtonElement>) => {
        if (asChild && isDisabled) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }

        onClickCapture?.(event);
      },
      [asChild, isDisabled, onClickCapture],
    );

    React.useLayoutEffect(() => {
      if (hasIconMotion) ensureButtonIconKeyframes();
    }, [hasIconMotion]);

    return (
      <Comp
        ref={ref}
        className={buttonVariants({
          variant,
          size,
          className: cn(
            hasIconMotion && "group",
            asChild && isDisabled && "pointer-events-none opacity-45",
            className,
          ),
        })}
        aria-disabled={asChild && isDisabled ? true : undefined}
        aria-busy={loading ? true : undefined}
        disabled={!asChild ? isDisabled : undefined}
        data-loading={loading ? "" : undefined}
        onClickCapture={handleClickCapture}
        tabIndex={asChild && isDisabled ? -1 : tabIndex}
        type={!asChild ? (type ?? "button") : undefined}
        {...props}
      >
        {loading && <ButtonSpinner />}
        {!loading && leftIcon && (
          <span
            className={cn(
              ICON_SHELL,
              leftIconMotion && leftIconMotionClass[leftIconMotion],
            )}
          >
            {leftIcon}
          </span>
        )}
        <span className="relative z-10 inline-flex items-center gap-2">
          {children}
        </span>
        {!loading && rightIcon && (
          <span
            className={cn(
              ICON_SHELL,
              rightIconMotion && rightIconMotionClass[rightIconMotion],
            )}
          >
            {rightIcon}
          </span>
        )}
      </Comp>
    );
  },
);

Button.displayName = "Button";

function ButtonSpinner() {
  return (
    <span
      aria-hidden="true"
      className="relative z-10 size-3.5 shrink-0 rounded-full border-2 border-current border-r-transparent opacity-80 motion-safe:animate-spin"
    />
  );
}

export interface ButtonGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  orientation?: "horizontal" | "vertical";
}

export function ButtonGroup({
  className,
  orientation = "horizontal",
  ...props
}: ButtonGroupProps) {
  return (
    <div
      role="group"
      className={cn(
        "relative inline-flex overflow-hidden rounded-[10px] border border-[var(--border-strong)] bg-transparent",
        orientation === "horizontal" ? "flex-row items-stretch" : "flex-col",
        className,
      )}
      {...props}
    />
  );
}

const groupItemClass =
  "rounded-none border-0 shadow-none " +
  "focus-visible:relative focus-visible:z-10 hover:z-10 " +
  "[&:not(:last-child)]:border-r [&:not(:last-child)]:border-[var(--border-strong)]";

export type ButtonGroupItemProps = ButtonProps;

export const ButtonGroupItem = React.forwardRef<
  HTMLButtonElement,
  ButtonGroupItemProps
>(({ className, variant = "outline", ...props }, ref) => {
  return (
    <Button
      ref={ref}
      variant={variant}
      className={cn(groupItemClass, className)}
      {...props}
    />
  );
});

ButtonGroupItem.displayName = "ButtonGroupItem";

export interface ButtonGroupSeparatorProps
  extends React.HTMLAttributes<HTMLDivElement> {
  orientation?: "horizontal" | "vertical";
}

export function ButtonGroupSeparator({
  className,
  orientation = "vertical",
  ...props
}: ButtonGroupSeparatorProps) {
  return (
    <div
      role="separator"
      aria-orientation={orientation}
      className={cn(
        "shrink-0 bg-[var(--border-strong)]",
        orientation === "vertical" ? "w-px self-stretch" : "h-px w-full",
        className,
      )}
      {...props}
    />
  );
}

export function ButtonGroupMenu(
  props: React.ComponentProps<typeof DropdownMenu.Root>,
) {
  return <DropdownMenu.Root modal={false} {...props} />;
}

const menuTriggerClass =
  "data-[state=open]:z-20 data-[state=open]:bg-[color-mix(in_srgb,var(--foreground)_4%,transparent)]";

export const ButtonGroupMenuTrigger = React.forwardRef<
  HTMLButtonElement,
  ButtonGroupItemProps
>(({ className, ...props }, ref) => {
  return (
    <DropdownMenu.Trigger asChild>
      <ButtonGroupItem
        ref={ref}
        className={cn(menuTriggerClass, className)}
        {...props}
      />
    </DropdownMenu.Trigger>
  );
});

ButtonGroupMenuTrigger.displayName = "ButtonGroupMenuTrigger";

export interface ButtonGroupMenuContentProps
  extends React.ComponentPropsWithoutRef<typeof DropdownMenu.Content> {
  align?: "start" | "center" | "end";
  sideOffset?: number;
}

export function ButtonGroupMenuContent({
  className,
  align = "end",
  sideOffset = 8,
  ...props
}: ButtonGroupMenuContentProps) {
  return (
    <DropdownMenu.Portal>
      <DropdownMenu.Content
        align={align}
        sideOffset={sideOffset}
        collisionPadding={12}
        className={cn(
          "z-50 min-w-[12.5rem] origin-top-right overflow-hidden rounded-[10px] border border-[var(--border-strong)] bg-[var(--surface)] p-1",
          "shadow-[0_1px_2px_rgba(0,0,0,0.06),0_12px_32px_-10px_rgba(0,0,0,0.22)]",
          "dark:shadow-[0_12px_32px_-10px_rgba(0,0,0,0.62)]",
          "data-[state=open]:animate-in data-[state=open]:fade-in-0",
          "data-[state=closed]:animate-out data-[state=closed]:fade-out-0",
          className,
        )}
        {...props}
      />
    </DropdownMenu.Portal>
  );
}

export interface ButtonGroupMenuItemProps
  extends React.ComponentPropsWithoutRef<typeof DropdownMenu.Item> {
  icon?: React.ReactNode;
  destructive?: boolean;
  shortcut?: string;
}

export const ButtonGroupMenuItem = React.forwardRef<
  HTMLDivElement,
  ButtonGroupMenuItemProps
>(
  (
    { className, children, icon, destructive = false, shortcut, ...props },
    ref,
  ) => {
    return (
      <DropdownMenu.Item
        ref={ref}
        className={cn(
          "group/menu-item relative flex cursor-pointer select-none items-center gap-2.5 rounded-[7px] px-2.5 py-2 text-sm outline-none",
          "transition-colors duration-150",
          destructive
            ? "text-red-600 data-[highlighted]:bg-red-500/10 data-[highlighted]:text-red-600 dark:text-red-400 dark:data-[highlighted]:text-red-400"
            : "text-[var(--foreground)] data-[highlighted]:bg-[color-mix(in_srgb,var(--foreground)_6%,transparent)]",
          "data-[disabled]:pointer-events-none data-[disabled]:opacity-45",
          className,
        )}
        {...props}
      >
        {icon ? (
          <span
            className={cn(
              "inline-flex size-4 shrink-0 items-center justify-center [&_svg]:size-4",
              destructive
                ? "text-red-500/90 dark:text-red-400/90"
                : "text-[var(--muted-foreground)] group-data-[highlighted]/menu-item:text-[var(--foreground)]",
            )}
          >
            {icon}
          </span>
        ) : null}
        <span className="min-w-0 flex-1 truncate">{children}</span>
        {shortcut ? (
          <span className="ml-auto shrink-0 text-[11px] tabular-nums text-[var(--muted-foreground)]">
            {shortcut}
          </span>
        ) : null}
      </DropdownMenu.Item>
    );
  },
);

ButtonGroupMenuItem.displayName = "ButtonGroupMenuItem";

export function ButtonGroupMenuSeparator({
  className,
  ...props
}: React.ComponentPropsWithoutRef<typeof DropdownMenu.Separator>) {
  return (
    <DropdownMenu.Separator
      className={cn("my-1 h-px bg-[var(--border-strong)]", className)}
      {...props}
    />
  );
}

export function ButtonGroupMenuLabel({
  className,
  ...props
}: React.ComponentPropsWithoutRef<typeof DropdownMenu.Label>) {
  return (
    <DropdownMenu.Label
      className={cn(
        "px-2.5 py-1.5 text-[11px] font-medium uppercase text-[var(--muted-foreground)]",
        className,
      )}
      {...props}
    />
  );
}
